#!/usr/bin/env python3
"""
Comprehensive test script to verify the update_progress fix handles various scenarios correctly.
"""

from sepal_ui import sepalwidgets as sw

def test_backward_compatibility():
    """Test that existing [0,1] usage still works correctly"""
    print("=== Testing Backward Compatibility ===")

    alert = sw.Alert()

    # Test normalized progress values
    test_values = [0.0, 0.25, 0.5, 0.75, 1.0]
    for progress in test_values:
        try:
            alert.update_progress(progress)
            expected_n = progress * 100  # Default total is 100
            actual_n = alert.progress_bar.n
            if abs(actual_n - expected_n) < 0.01:  # Allow for floating point precision
                print(f"✓ Progress {progress}: {actual_n}/100")
            else:
                print(f"✗ Progress {progress}: expected ~{expected_n}, got {actual_n}")
        except Exception as e:
            print(f"✗ Progress {progress} failed: {e}")

    # Test completion
    try:
        alert_complete = sw.Alert()
        alert_complete.update_progress(1.0)
        # After completion, progress_bar should be closed
        print("✓ Completion handling works")
    except Exception as e:
        print(f"✗ Completion handling failed: {e}")

def test_absolute_values():
    """Test absolute progress values with custom totals"""
    print("\n=== Testing Absolute Values ===")

    # Test case 1: 50 out of 200
    alert1 = sw.Alert()
    try:
        alert1.update_progress(50, total=200)
        if abs(alert1.progress_bar.n - 50) < 0.01:
            print(f"✓ Absolute progress 50/200: {alert1.progress_bar.n}/200")
        else:
            print(f"✗ Absolute progress 50/200: expected 50, got {alert1.progress_bar.n}")
    except Exception as e:
        print(f"✗ Absolute progress 50/200 failed: {e}")

    # Test case 2: Update to 150 out of 200
    try:
        alert1.update_progress(150, total=200)  # total should be ignored on subsequent calls
        if abs(alert1.progress_bar.n - 150) < 0.01:
            print(f"✓ Updated progress 150/200: {alert1.progress_bar.n}/200")
        else:
            print(f"✗ Updated progress 150/200: expected 150, got {alert1.progress_bar.n}")
    except Exception as e:
        print(f"✗ Updated progress 150/200 failed: {e}")

    # Test case 3: Completion with absolute values
    try:
        alert2 = sw.Alert()
        alert2.update_progress(100, total=100)
        print(f"✓ Absolute completion 100/100: {alert2.progress_bar.n}/100")
    except Exception as e:
        print(f"✗ Absolute completion 100/100 failed: {e}")

def test_edge_cases():
    """Test edge cases and boundary conditions"""
    print("\n=== Testing Edge Cases ===")

    # Test negative values (should work with tqdm)
    try:
        alert_neg = sw.Alert()
        alert_neg.update_progress(-10, total=100)
        print(f"✓ Negative progress handled: {alert_neg.progress_bar.n}/100")
    except Exception as e:
        print(f"✗ Negative progress failed: {e}")

    # Test very large values
    try:
        alert_large = sw.Alert()
        alert_large.update_progress(1000, total=100)
        print(f"✓ Large progress handled: {alert_large.progress_bar.n}/100")
    except Exception as e:
        print(f"✗ Large progress failed: {e}")

    # Test zero progress
    try:
        alert_zero = sw.Alert()
        alert_zero.update_progress(0)
        if abs(alert_zero.progress_bar.n - 0) < 0.01:
            print(f"✓ Zero progress handled: {alert_zero.progress_bar.n}/100")
        else:
            print(f"✗ Zero progress failed: {alert_zero.progress_bar.n}/100")
    except Exception as e:
        print(f"✗ Zero progress failed: {e}")

def test_mixed_usage():
    """Test mixing normalized and absolute values"""
    print("\n=== Testing Mixed Usage ===")

    # Start with normalized, then absolute (with total parameter)
    try:
        alert_mixed = sw.Alert()
        alert_mixed.update_progress(0.5)  # 50% of default 100 = 50
        print(f"After normalized 0.5: {alert_mixed.progress_bar.n}/100")

        # This should be treated as absolute since > 1
        alert_mixed.update_progress(75, total=100)  # total ignored on subsequent calls
        print(f"After absolute 75: {alert_mixed.progress_bar.n}/100")
        print("✓ Mixed usage handled correctly")
    except Exception as e:
        print(f"✗ Mixed usage failed: {e}")

if __name__ == "__main__":
    test_backward_compatibility()
    test_absolute_values()
    test_edge_cases()
    test_mixed_usage()
